{{-- "Direct Call on evoory" card (from the profile page's Call me now popup),
     shared by My Account and Help. Call Now starts a website call to Support:
     data-rtc-support fans it out to every admin through webrtc-scripts.

     $supportConversationId — the user's Support conversation. Null for a
     guest, whose Call Now runs the host component's loginToCall() instead,
     since website calls need an account. --}}
<style>
    .ev-am-direct {
        display: flex;
        align-items: center;
        gap: 10px;
        margin: 0 20px 12px;
        padding: 12px 12px 12px 14px;
        border-radius: 12px;
        background: #C1F11D14;
        text-align: left;
    }
    .ev-am-direct__main { flex: 1 1 auto; min-width: 0; display: flex; align-items: center; gap: 10px; }
    .ev-am-direct__icon {
        flex-shrink: 0;
        width: 24px; height: 24px;
        border-radius: 50%;
        background: #C1F11D;
        color: #0a0a0a;
        display: inline-flex; align-items: center; justify-content: center;
    }
    .ev-am-direct__text { flex: 1; min-width: 0; display: block; }
    .ev-am-direct__title { color: #fff; font-size: 14px; font-weight: 600; line-height: 1.25; display: flex; align-items: center; gap: 2px 5px; flex-wrap: wrap; }
    .ev-am-direct__brand { display: inline-flex; align-items: center; }
    .ev-am-direct__sub { display: block; color: #8c9196; font-size: 11.5px; line-height: 1.35; margin-top: 2px; }
    .ev-am-direct__btn {
        flex-shrink: 0;
        display: inline-flex; align-items: center; justify-content: center; gap: 2px;
        padding: 4px 8px;
        white-space: nowrap;
        border: none;
        border-radius: 999px;
        background: #C1F11D;
        color: #0a0a0a !important;
        font-size: 12px;
        font-weight: 600;
        cursor: pointer;
        transition: background 150ms;
    }
    .ev-am-direct__btn:hover { background: #b1dc1a; }
    .ev-am-direct svg {
        transform: none !important;
        -webkit-transform: none !important;
        margin: 0 !important;
    }
    .ev-am-direct__icon svg { width: 12px !important; height: 12px !important; }
    .ev-am-direct__brand svg { width: 62px !important; height: 16px !important; }
    .ev-am-direct__btn svg { width: 14px !important; height: 14px !important; }
    @media (max-width: 420px) {
        .ev-am-direct { margin-inline: 0; }
    }
</style>
<div class="ev-am-direct">
    <div class="ev-am-direct__main">
        <span class="ev-am-direct__icon">
            <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"/></svg>
